4: type TiltProps = {
5:   children: ReactNode;
6:   className?: string;
7:   /** maximum rotation in degrees at the edges */
8:   max?: number;
9: };
10: 
11: /**
12:  * Pointer-following tilt for the window screenshots.
13:  * Pointer only: touch devices and reduced-motion users get a static frame.
14:  */
15: export function Tilt({ children, className = '', max = 3.4 }: TiltProps) {
16:   const ref = useRef<HTMLDivElement>(null);
17: 
18:   useEffect(() => {
19:     const el = ref.current;
20:     if (!el) return;
21: 
22:     const still = window.matchMedia('(prefers-reduced-motion: reduce)');
23:     let frame = 0;
24: 
25:     const move = (event: PointerEvent) => {
26:       /* touch and pen drags should never bend the window */
27:       if (event.pointerType !== 'mouse' || still.matches) return;
28: 
29:       const rect = el.getBoundingClientRect();
30:       const px = Math.min(1, Math.max(0, (event.clientX - rect.left) / rect.width));
31:       const py = Math.min(1, Math.max(0, (event.clientY - rect.top) / rect.height));
32: 
33:       cancelAnimationFrame(frame);
34:       frame = requestAnimationFrame(() => {
35:         el.style.setProperty('--rx', `${(0.5 - py) * max * 2}deg`);
36:         el.style.setProperty('--ry', `${(px - 0.5) * max * 2}deg`);
37:         el.style.setProperty('--mx', `${px * 100}%`);
38:         el.style.setProperty('--my', `${py * 100}%`);
39:         el.classList.add('is-tilting');
40:       });
41:     };
42: 
43:     const reset = () => {
44:       cancelAnimationFrame(frame);
45:       el.classList.remove('is-tilting');
46:       el.style.removeProperty('--rx');
47:       el.style.removeProperty('--ry');
48:       el.style.removeProperty('--mx');
49:       el.style.removeProperty('--my');
50:     };
51: 
52:     el.addEventListener('pointermove', move);
53:     el.addEventListener('pointerleave', reset);
54:     el.addEventListener('blur', reset);
55:     return () => {
56:       cancelAnimationFrame(frame);
57:       el.removeEventListener('pointermove', move);
58:       el.removeEventListener('pointerleave', reset);
59:       el.removeEventListener('blur', reset);
60:     };
61:   }, [max]);
62: 
63:   return (
64:     <div ref={ref} className={`tilt ${className}`.trim()}>
65:       <div className="tilt__inner">{children}</div>
66:     </div>
67:   );
68: }

